        defense: [E(.statement, 1, "Passing", "{DL} says {D.he} was passing through.")],
        role: "Florist",
        exam: [.direct("What happened at your flower shop on {DATE}?", "\"The back door was pried open, and a cash box and wreath stock were taken.\""), .direct("What ties {DL} to it?", "\"A pry bar in {D}'s truck matches the tool marks on my door. A street camera shows {D}'s truck near the lot.\""), .direct("What was missing?", "\"The cash box and my wreath stock. The inventory is in evidence.\""), .direct("Please tell us about your flower shop.", "\"I own a small florist shop. I do weddings, funerals, and weekly arrangements, and I keep wreath stock and a cash box in the back room.\""), .direct("What did you find when you arrived that morning?", "\"The back door was pried open, the cash box was gone, and a stack of wreaths was missing. I called the deputies right away.\""), .direct("How was {D}'s truck connected to the break-in?", "\"A street camera shows {D}'s truck near the lot at about one in the morning. A pry bar in the truck matched the marks on my door.\""), .cross("{DL} says {D.he} was passing through, doesn't {D.he}?", "\"A truck on a street isn't proof of entry. I only know it was near.\""), .cross("Is the pry bar a common brand?", "\"I'm told it is. Many people own one. It matches my door's marks.\""), .cross("Did you see {DL} at your shop?", "\"No. I wasn't there at night. I rely on the camera and the marks.\""), .cross("Did you see anyone take the items?", "\"No. I arrived at eight and found the damage. I did not see who did it, and I cannot say who was at the door that night.\""), .cross("Is the pry bar a very common tool?", "\"I am told it is a common brand. Many people own one, and the marks match, but I cannot say whose bar made them.\"")],
        defenseRole: "Flea market vendor",
        defenseExam: [.direct("Do you sell at the flea market?", "\"Yes. I run a booth on weekends. I know many sellers.\""), .direct("Do you know {DL}?", "\"Yes. I've seen {D} around. {D} sells and buys small things.\""), .direct("What do you know about the break-in?", "\"Only what I heard. I don't know anything.\""), .direct("Please tell us about your booth at the flea market.", "\"I run a booth on weekends selling antiques and crafts. I have been at the same spot for many years, and I know most of the other vendors.\""), .direct("How do you know {D}?", "\"I have seen {D} at the market for years. {D} sells wreaths at a booth a few rows from mine, and we often talk while setting up.\""), .direct("What do you know about {D}'s wreaths?", "\"They are handmade. {D} buys supplies at a craft store and makes the wreaths at home. I have seen {D} stringing them together on slow days.\""), .cross("Did you see {DL} that night?", "\"No. I wasn't there.\""), .cross("Did {DL} sell wreaths?", "\"I don't recall. I can't say.\""), .cross("Do you know the pry bar?", "\"No. I know nothing about it.\""), .cross("Did you see {D} on the night of the break-in?", "\"No. I was not there. I only know what {D} told me, which is that {D} was driving home from a job when the lot was nearby.\""), .cross("Do you know where {D} got the wreaths that were on sale?", "\"I assumed {D} made them. I did not see where each one came from, and I cannot say none of them were from the florist.\"")],
        theory: ("{D} burgled a florist.", "A passerby."),
