        spec: "Broke and entered a building, a middle school owned by {V}, with intent to commit larceny, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "Sound equipment worth $17,000 was taken from an auditorium on {DATE}. A former tech volunteer, {D}, had a key. {DL} says the key was lost.",
        state: [E(.document, 3, "Key Log", "A key issued to {D}."), E(.video, 2, "Hall Camera", "A figure with a cart."), E(.physical, 3, "Pawn Item", "A mixer traced to {D}.", .search)],
        defense: [E(.statement, 1, "Lost Key", "{DL} says the key was lost.")],
        role: "Drama director",
        exam: [.direct("What was taken from the auditorium on {DATE}?", "\"Sound equipment worth $17,000. A camera shows a figure with a cart in the hall.\""), .direct("Who had a key?", "\"{D}, a former tech volunteer. The key log shows a key issued to {D}.\""), .direct("What was recovered?", "\"A mixer traced to {D} through a pawn record. It was found in a search.\""), .direct("Tell us about your job at the school.", "\"I direct the school's drama program. The auditorium is where we hold rehearsals and performances, and I am responsible for the sound equipment and for who has keys.\""), .direct("What did you find that morning?", "\"At about seven, I found the sound booth empty. The mixer, speakers, and microphones, worth about $17,000, were all gone, and nothing was forced open.\""), .direct("How was {D} connected to the equipment?", "\"{D} was a tech volunteer who held a key, and the key log shows it was issued to {D}. A mixer traced to {D} was later found through a pawn record.\""), .cross("{DL} says the key was lost, doesn't {D.he}?", "\"I have no record of it being reported lost at the time.\""), .cross("Can you identify the figure with the cart?", "\"No. The image is grainy. I can't say who it is.\""), .cross("Did others have keys?", "\"A few people. I can't say all keys are accounted for.\""), .cross("Did {D} ever tell you the key was lost?", "\"I have no record of that. If a key had been reported lost, I would have changed the lock or at least written it down in the log.\""), .cross("Can you tell who is on the hall camera?", "\"No. The figure pushes a cart in the dark. I cannot tell the build or the face, and I cannot say it is {D}.\"")],
        defenseRole: "Parent volunteer",
        defenseExam: [.direct("Do you volunteer at the school?", "\"Yes. I'm a parent volunteer. I know {D} from the tech crew.\""), .direct("Did {DL} lose a key?", "\"I heard {D} mention a missing key. I don't remember when.\""), .direct("Please tell us about your time as a parent volunteer.", "\"My child is in the drama club and I volunteer at nearly every show. I help with costumes, tickets, and stage crew, and I have worked beside {D} many times.\""), .direct("What did {D} say about a missing key?", "\"Months before the theft, {D} mentioned in passing that a key had gone missing. I remember it because we were loading a van, and I thought nothing of it.\""), .direct("What kind of volunteer was {D}?", "\"Reliable and generous with time. {D} stayed late to fix lights and never asked for anything. I would not have guessed {D} would take equipment from the school.\""), .direct("What did {D} do during the years as a volunteer?", "\"{D} ran the sound board for school events and was always the last one to leave. {D} knew the auditorium better than most staff.\""), .cross("Did {DL} tell the director?", "\"I don't know. I didn't hear.\""), .cross("Did you see {DL} with equipment?", "\"No. I never did.\""), .cross("Do you know about the pawn?", "\"Only what I've heard.\""), .cross("Did {D} tell the director about the lost key?", "\"I do not know. I did not hear any conversation with the director, and I cannot say whether the director was ever told about it.\""), .cross("Did you ever see {D} move equipment out of the school?", "\"No. I never saw that. I only saw {D} bring items in for shows, and I do not know anything about a pawn shop.\"")],
        theory: ("{D} took equipment.", "A lost key."),
        allocution: "\"I took what wasn't mine, and I'm sorry for it.\"",
        truths: ("{DL} pawned the mixer.", "The key was reported lost earlier."),
        defendant: [.direct("Did you take the equipment?", "\"No. I volunteered for years. I'd never take from the school.\""), .direct("What about the mixer?", "\"I pawned a mixer I owned. I thought it was mine. I didn't know it was the school's.\""), .direct("Please tell us about your years as a volunteer.", "\"I helped with the tech crew for several years, setting up lights and sound. I enjoyed it, and I gave a lot of weekends to those shows.\""), .direct("What happened with your key?", "\"I lost it months before, and I do not remember exactly when. I mentioned it to a parent volunteer, though I did not tell the director.\""), .direct("Why did you pawn a mixer?", "\"I owned a mixer of my own and I thought it was the one I brought from home. I was short on money, so I pawned it, and I did not realize it was the school's.\""), .direct("What did you do with the key after your last day as a volunteer?", "\"I put it on a ring and forgot about it. When I noticed it gone, I figured it fell off at the school, and I never reported it.\""), .cross("A mixer traced to you was the school's, wasn't it?", "\"That's what they say. I'm shocked. I believed it was mine.\""), .cross("You had a key to the auditorium, didn't you?", "\"I did, once. I lost it. Someone may have found it.\""), .cross("$17,000 is a lot of equipment, isn't it?", "\"Yes. I had nothing to do with most of it.\""), .cross("You mixed up your own mixer with the school's, did you?", "\"It looks that way. They were similar models. I was sure it was mine, and I was shocked when I learned it belonged to the school.\""), .cross("You never reported the lost key in writing, did you?", "\"No. I wish I had. I only mentioned it in passing, and I know that does not look good now that the equipment is missing.\"")],
        openings: ("Sound equipment worth $17,000 vanished from a school auditorium overnight. A key to the building had been issued to {D}, a former tech volunteer, and a mixer from the school turned up in a pawn shop under {D}'s name.", "The defense will point you to a lost key, a longtime volunteer who gave years to this school, and a mixer {D} honestly believed was {D.his} own. A mix-up is not a burglary, and the State must prove otherwise."),
        closings: ("A key issued to {D}, a figure with a cart on the hall camera, and the school's mixer pawned under {D}'s name. {D} had a key, had a reason to need money, and said nothing to the director.", "A lost key and a mixer {D} thought was {D.his} own. The State has not proved {D} entered the auditorium that night, and a volunteer who gave years to the school deserves the benefit of doubt."),
        timeline: [(-30, "The key is lost, {DL} says."), (0, "Midnight: the cart."), (0, "7 a.m.: the director."), (2, "The mixer turns up.")],
        identified: "A key log.",
        aggravating: ["The offense was committed for pecuniary gain"],
        mood: .wantsConviction,
        impact: "Students lost the spring show.",
        doctrines: ["burdenOfProof"])

    static let churchOfficeSafeV1 = SmallCases.make(
        key: "story.churchOfficeSafe",
        category: .property,
        headlines: ["Parish Hall Offering Vault Opened With Angle Grinder After Bake Sale Weekend", "Grinder Blade Debris and a Missing Tool From a Roofing Crew"],
        law: "burglary2",
        threshold: 8,
        spec: "Broke and entered a building, a church owned by {V}, with intent to commit larceny, on {DATE}.",
