        state: [E(.physical, 3, "Blade Guard", "A green guard matching {D}'s grinder."), E(.forensic, 3, "Cut Marks", "The cut matches an angle grinder blade."), E(.statement, 2, "Pastor", "Saw {D}'s crew near the hall."), E(.video, 1, "Parking Lot Camera", "A truck at 2 a.m.")],
        defense: [E(.statement, 1, "Lent the Grinder", "{DL} says a friend borrowed it."), E(.statement, 1, "Home That Night", "{DL} says {D.he} was home.")],
        role: "Pastor",
        exam: [.direct("What did you find at the parish hall on {DATE}?", "\"A steel offering vault cut open with an angle grinder and $9,500 from a bake sale and a fundraiser dinner taken. Metal shavings and a green blade guard were on the floor.\""), .direct("What did the blade guard show?", "\"It's a green guard matching the angle grinder missing from {D}'s truck. A roofing crew had worked at the church the week before.\""), .direct("Whom did you see?", "\"I saw {D}'s crew near the hall that week. A parking lot camera shows a truck at 2 a.m.\""), .direct("Tell the jury about your church and the parish hall.", "\"I am the pastor here. The parish hall hosts our bake sales, dinners, and meetings, and we keep the offering money in a steel vault in the office.\""), .direct("What did you find when you arrived at seven that morning?", "\"The vault door was cut open, and metal shavings were all over the floor. About $9,500 from the bake sale and fundraiser dinner was gone.\""), .direct("Why did you tell the deputies about the roofing crew?", "\"A roofing crew had worked on our roof the week before, and {D}'s crew was one of them. I saw them near the hall every day that week.\""), .cross("{DL} says a friend borrowed the grinder, doesn't {D.he}?", "\"I can't say who had it that night.\""), .cross("Did you see {DL} that night?", "\"No. I was asleep. I only saw the crew earlier.\""), .cross("Are green guards unique?", "\"No. They're a common brand. They match one missing grinder, but not only one.\""), .cross("Did you see {D} at the church that night?", "\"No. I was home asleep. I did not see anyone at the hall, and I cannot say who was in the parking lot at two in the morning.\""), .cross("Could someone else have used a green angle grinder?", "\"Possibly. I am told green guards are common. But this guard matches the one missing from {D}'s truck, and that is why I mentioned the crew.\"")],
        theory: ("{D} used a work grinder to open a church vault.", "A roofer whose tool was borrowed."),
        allocution: "\"I'm ashamed of it, Your Honor. I want to make it right.\"",
        truths: ("{DL} could not name the friend who borrowed the grinder.", "{DL} had a new grinder on the receipt from the next day."),
        defendant: [.direct("Where was your grinder?", "\"I lent it to a friend. It was out of my truck before the break-in.\""), .direct("Where were you that night?", "\"At home asleep. I didn't go near the church. I'd never rob a church.\""), .direct("Why was a guard from your grinder at the scene?", "\"I don't know. Someone with the grinder left it. It wasn't me.\""), .direct("Describe your roofing crew's work at the church for the jury.", "\"We replaced part of the roof over a few days the week before. We were friendly with the pastor, and we cleaned up each afternoon.\""), .direct("What happened to your grinder?", "\"I lent it to a friend a few days before the break-in. The friend needed to cut some metal, and I did not think anything of it.\""), .direct("Why did you buy a new grinder the next day?", "\"I needed one for a job. My lent grinder had not been returned, so I bought a new one, and I kept the receipt.\""), .cross("Your crew worked at the church the week before, didn't it?", "\"Yes. We did a roof. We were there in daylight.\""), .cross("You can't prove who borrowed the grinder, can you?", "\"I know the friend, but I can't reach them. I know that's weak.\""), .cross("The cut matches an angle grinder, doesn't it?", "\"I'm told so. Many people own one. It wasn't mine that night.\""), .cross("You cannot name the friend who borrowed the grinder, can you?", "\"I know the friend by a nickname, and I have not been able to reach the friend since. I know that sounds weak to the jury.\""), .cross("A green guard matching your grinder was left at the scene, wasn't it?", "\"That is what they say. Many grinders have green guards. If the guard is from my grinder, then whoever had it left it there.\"")],
        openings: ("A church's steel offering vault was cut open with an angle grinder and $9,500 taken. A green blade guard left on the floor matches a grinder missing from {D}'s truck, and {D}'s roofing crew had worked at the church. The State will show the guard and the cut marks.", "The defense will present a grinder that was lent to a friend, a roofing crew that worked openly in daylight, and no one who saw {D} at the church that night."),
        closings: ("A steel vault cut open with an angle grinder, a green blade guard matching {D}'s grinder, a crew that worked there the week before, and a truck in the lot at two in the morning.", "A common grinder lent to a friend. The State has not proved {D} was at the church that night, and a tool left behind points to whoever held it, not to the one who lent it."),
        timeline: [(-7, "{D}'s crew works at the church."), (0, "2 a.m.: a truck in the lot."), (0, "2:30 a.m.: the vault is cut."), (0, "7 a.m.: the pastor finds the hall."), (1, "The blade guard is collected.")],
        identified: "A blade guard.",
        mood: .wantsConviction,
        doctrines: ["searchSeizure"])

    static let vanWithSleepingChildV1 = SmallCases.make(
