        defense: [E(.statement, 1, "Landlord", "{DL} says {D.he} only rented space.")],
        role: "Shipping company manager",
        exam: [.direct("What was stolen from your company?", "\"A box truck of electronics worth $120,000. GPS tracked it to a yard leased by {D}.\""), .direct("What was missing from the load?", "\"Six televisions were missing from the boxes that were sold. The rest remained.\""), .direct("What can you tell us about your job as a shipping company manager?", "\"I manage dispatch for a shipping company. I assign drivers, track loads by GPS, and I am responsible for the cargo while it is in our trucks.\""), .direct("What was stolen, and how did you notice?", "\"A box truck with $120,000 in electronics was taken about one in the morning. The GPS alert told us the truck was moving when it should have been parked.\""), .direct("What did deputies find at the yard?", "\"The truck itself was parked at the yard, and electronics boxes were in a shed there. The lease shows {D} rents that yard.\""), .direct("What did you do when you learned the truck was missing?", "\"I checked our dispatch log and called the driver. When no one answered, I pulled up the GPS and called the sheriff's office.\""), .cross("{D} says {D.he} only rented space, doesn't {D.he}?", "\"Yes. A person paid {D} to park the truck. I will agree that {D} may have been paid.\""), .cross("Did {D} sell any of the electronics?", "\"I understand {D} sold six televisions. I do not know more than that.\""), .cross("Did anyone see {D} drive the truck?", "\"No. The GPS only shows where the truck went. I cannot say who was behind the wheel, and nobody at our company saw the theft happen.\""), .cross("Could someone else have paid {D} to park the truck there?", "\"That is what {D} says. I cannot prove otherwise, but the truck ended up on {D}'s lease, and six televisions were missing from the load.\""), .cross("You did not see who parked the truck at the yard, did you?", "\"No. I only know where the GPS placed it and what deputies found. I never saw anyone park it.\"")],
        defenseRole: "Truck stop attendant",
        defenseExam: [.direct("Who drove the box truck into the truck stop?", "\"A person in a cap. I saw the truck pull in and park, but I did not see the face clearly.\""), .direct("Was the driver {D}?", "\"Unclear. It could have been, but I did not get a good look at the face under the cap.\""), .direct("How did the driver act when parking?", "\"Calm. The driver parked and walked away. I thought nothing of it at the time.\""), .direct("Please tell us about your work at the truck stop.", "\"I work the night desk at a truck stop. I watch the lot, check in drivers, and see many trucks come and go through the evening.\""), .direct("What did you see the night the box truck arrived?", "\"I saw a person in a cap drive a box truck onto the lot, park it, and walk away. I did not think it was unusual at the time.\""), .direct("How would you describe the driver's behavior?", "\"The driver was calm. There was no hurry and no sign of anything wrong. The driver parked, took a bag, and walked toward the road.\""), .cross("Did {D} take cash from the driver of the truck?", "\"I do not know. I did not see money change hands.\""), .cross("Can you describe the driver in more detail than a cap?", "\"No. Average height. I really cannot say more.\""), .cross("Did you see {D} at the truck stop at all that day?", "\"I saw {D} around the lot at times. {D} rents space nearby, so seeing {D} is normal, but I did not see {D} with that truck.\""), .cross("Could the driver have been {D}?", "\"I cannot say for certain. It was dark, and the driver wore a cap. I can only say I did not recognize the driver as {D}.\""), .cross("You did not see who took the electronics out of the truck, did you?", "\"No. I saw the truck pull in and the driver walk away. I did not see anything moved after that.\"")],
        theory: ("{D} stole a truck.", "A landlord."),
        allocution: "\"I wish I hadn't.\"",
        truths: ("{DL} sold six televisions.", "A man paid {DL} to park it."),
        defendant: [.direct("Did you steal the box truck of electronics?", "\"No. I did not steal it. A person paid me to park it on my yard, and I did not look inside.\""), .direct("Why was the truck on your yard?", "\"I rent out space. A person paid me for parking, and I did not ask what the truck was carrying.\""), .direct("Did you sell any of the electronics?", "\"I sold six televisions. I believed they belonged to the person who rented the space.\""), .direct("Tell the jury about your yard.", "\"I lease a fenced yard and sublet space for parking and storage. People pay me by the week, and I do not usually ask what they store.\""), .direct("How did the box truck get on your yard?", "\"A person came by that night and paid me to park a truck for a few days. I did not ask questions, and I took the cash.\""), .direct("Why did you sell six televisions?", "\"I found boxes in the shed and thought the person had left them as payment. I sold six, and I did not know they came from a theft.\""), .cross("$120,000 in electronics sat on your yard. Did you not look?", "\"I did not. I should have, yes. It was not my business, I thought.\""), .cross("You sold televisions from a stolen load, didn't you?", "\"I did. I thought they were left as payment. I should have asked, and I see now that I made a terrible mistake.\""), .cross("You cannot name the person who paid you to park it, can you?", "\"No. I never got a name. It was cash and a short talk at night. I know that sounds incomplete, and I truly am sorry.\""), .cross("You sold six televisions from that truck, didn't you?", "\"Yes. I was paid to park the truck and I took a few as payment. I knew I should have asked more questions.\""), .cross("You did not report the truck to anyone, did you?", "\"No. I should have called the sheriff's office as soon as I saw what was inside. I was afraid of getting in trouble.\"")],
        openings: ("A box truck of electronics worth $120,000 was stolen, and GPS tracked it to a yard leased by {D}. Electronics boxes were found in {D}'s shed, and six televisions had been sold.", "The defense witnesses will explain that someone paid {D} to park the truck, that {D} did not drive it, and that {D} did not know what was inside."),
        closings: ("GPS to {D}'s yard, electronics boxes in {D}'s shed, and six televisions sold. The truck was not parked on {D}'s property by accident, and {D} knew what was aboard.", "A person in a cap drove the truck onto the yard, and no one saw {D} drive it. The State must prove {D} knew the cargo was stolen."),
        timeline: [(0, "1 a.m.: the truck is taken."), (0, "3 a.m.: it reaches the yard."), (1, "The company notices."), (2, "The search.")],
        identified: "GPS data.",
        aggravating: ["The offense was committed for pecuniary gain"],
        mood: .wantsConviction,
        doctrines: ["burdenOfProof"])

    static let calfBarnTheftV1 = SmallCases.make(
