        state: [E(.document, 3, "Sale Barn Receipt", "Fourteen goats consigned by {D} with {V}'s tag numbers."), E(.document, 3, "Tag Records", "{V}'s tag numbers match those on the receipt."), E(.physical, 2, "Trailer Tracks", "A bent axle matching {D}'s trailer."), E(.statement, 1, "Neighbor", "Heard a truck at 2 a.m.")],
        defense: [E(.statement, 1, "Bought Elsewhere", "{DL} says the goats came from another county."), E(.document, 1, "Cash Withdrawal", "{DL} withdrew $3,000 the week before.")],
        role: "Livestock owner",
        exam: [.direct("What did you lose on {DATE}?", "\"Fourteen goats were taken overnight from my pasture. A bent trailer axle left tracks along the gravel and into a field.\""), .direct("How did the goats surface?", "\"A week later, a sale barn recorded fourteen goats from {D} with ear tag numbers that match my records.\""), .direct("What do the tag records show?", "\"The tag numbers on the sale barn receipt match mine. A neighbor heard a truck at 2 a.m., and the axle tracks match {D}'s trailer.\""), .direct("Tell the jury about your goat operation.", "\"I raise goats on a pasture at the edge of my property. I tag every animal with a numbered ear tag and keep the tag numbers in a record book.\""), .direct("What did you find that morning?", "\"The gate was open and the pasture was empty. Fourteen goats were gone, and tracks from a bent trailer axle ran along the gravel and into a field.\""), .direct("How did you learn where the goats went?", "\"A week later the sale barn called me. A consignment of fourteen goats had tag numbers that matched my records, and the receipt showed {D} as the consignor.\""), .cross("{DL} says {D.he} bought them from a farmer in another county, doesn't {D.he}?", "\"I can't speak to a farmer I've never met.\""), .cross("Could the tags have been copied?", "\"Unlikely. They're registered. The numbers match mine.\""), .cross("Did you see {DL}?", "\"No. I was asleep. I rely on the records and the tracks.\""), .cross("Did any neighbor see the goats being loaded?", "\"One neighbor heard a truck around two in the morning, but nobody saw the loading or the driver. I cannot say who was at my gate.\""), .cross("Could a buyer have bought these goats without knowing they were stolen?", "\"Possibly. But the tags were still in their ears. Anyone looking would see numbers, and the sale came within a week of the theft.\"")],
        theory: ("{D} took goats and sold them at a sale barn.", "A buyer who was misled about the source."),
        allocution: "\"I took what wasn't mine, and I'm sorry for it.\"",
        truths: ("{DL} could not name the farmer who sold the goats.", "{DL} consigned the goats within a week of the theft."),
        defendant: [.direct("Where did you get the goats?", "\"From a farmer in another county. I paid cash and never looked at the tags.\""), .direct("Why did you take them to a sale barn?", "\"To sell them. I thought they were a good lot. I wasn't hiding anything.\""), .direct("Did you take {V}'s goats?", "\"No. I've never been on that pasture. I wouldn't steal animals.\""), .direct("What can you tell us about your livestock business?", "\"I buy and sell livestock part time. I look for good prices, and I have taken animals to sale barns many times over the years.\""), .direct("How did you pay for the goats?", "\"I withdrew cash from my bank and paid the farmer directly. It was a handshake deal, and I did not ask for a written bill of sale.\""), .direct("Did you look at the ear tags when you bought them?", "\"No. I never looked at the tag numbers. I was thinking about the price, and I trusted that the goats belonged to the seller.\""), .cross("The tag numbers match {V}'s records, don't they?", "\"So I'm told. I didn't look. I trusted the seller.\""), .cross("A bent axle matches your trailer, doesn't it?", "\"It's bent from hauling. Trailers get bent. That doesn't put it at the pasture.\""), .cross("You withdrew $3,000 the week before, didn't you?", "\"Yes. For the purchase. I know it's not proof.\""), .cross("You cannot name the farmer who sold you the goats, can you?", "\"I only know the farmer by a first name and a farm in another county. I have not been able to find that farm again.\""), .cross("Your trailer has a bent axle, doesn't it?", "\"Yes. It has been bent for a while. Many trailers have damage, and I was not at that pasture the night the goats disappeared.\"")],
        openings: ("Fourteen goats were taken from {V}'s pasture, a bent trailer axle left tracks, and a week later a sale barn took fourteen goats from {D} with ear tags matching {V}'s records. The State will show the receipt and the tag records.", "Jurors will also see goats bought from a farmer in another county, a cash withdrawal to pay for them, and a trailer that was bent from hauling."),
        closings: ("Fourteen goats gone, a bent axle in the tracks, and the same fourteen tag numbers at the sale barn from {D}. The tags settle whose goats they were.", "{D} bought the goats and sold them openly at a sale barn. The State has not proved {D} knew they were stolen."),
        timeline: [(0, "Night: the goats are taken."), (0, "Morning: {V} finds the gate open."), (2, "Tracks lead to a field."), (7, "The sale barn records the consignment."), (8, "{V}'s tags match.")],
        identified: "A sale barn receipt.",
        mood: .wantsConviction,
        doctrines: ["mistakeOfFact"])

    static let lumberLoadTheftV1 = SmallCases.make(
