        state: [E(.video, 3, "Site Camera", "A dented flatbed."), E(.document, 3, "Delivery Invoice", "{D} billed a customer for trusses."), E(.physical, 2, "Truss Stamps", "Stamps match the site.", .search)],
        defense: [E(.statement, 1, "Customer", "{DL} says a customer hired {D.him}.")],
        role: "Builder",
        exam: [.direct("What was taken from your subdivision lot?", "\"Roof trusses worth $16,000. They were taken from a new lot, and a site camera photographed a dented flatbed.\""), .direct("What matched the flatbed?", "\"{D}'s flatbed has a matching dent. {D} also billed a customer for trusses, and the truss stamps match my site.\""), .direct("What do the stamps show?", "\"They match my site's stamps on the trusses that were recovered.\""), .direct("Tell us about your work as a builder.", "\"I build homes in a new subdivision. I order materials like roof trusses ahead of the framing crew, and I keep the loads on the lots until they are used.\""), .direct("What did you find when you arrived at the lot?", "\"The trusses I had delivered, worth about $16,000, were gone. The stack was bare, and tire marks led from the stack to the road.\""), .direct("How did you connect {D}'s flatbed to the theft?", "\"A site camera shows a dented flatbed at about nine that night. {D}'s flatbed has a matching dent, and the trusses carried my site's stamps.\""), .cross("{D} says {D.he} was hauling for a customer, doesn't {D.he}?", "\"Yes. A customer says so. I will agree that the customer exists.\""), .cross("Did {D} bill the customer in cash?", "\"I understand so. That is what the invoice says.\""), .cross("Many flatbeds have dents, don't they?", "\"Many do. But this dent matches in several ways.\""), .cross("Did you see the flatbed driver's face on the camera?", "\"No. The video shows the truck and a dent, but not the driver's face. I cannot say who sat behind the wheel.\""), .cross("Is it possible that {D} hauled trusses for someone else?", "\"It is possible that {D} hauls for customers. But the stamps on these trusses match my site, and I did not authorize anyone to take them.\"")],
        defenseRole: "Customer",
        defenseExam: [.direct("Did you hire {D} to haul trusses for you?", "\"Yes. I hired {D} to deliver a load of trusses to my project, and we agreed on a price.\""), .direct("Did you believe these trusses were meant for your job?", "\"I thought so. {D} told me it was a load I had ordered, and I had no reason to doubt it.\""), .direct("How did you pay {D} for the delivery?", "\"In cash. That is how we agreed. I have a record of the payment in my phone.\""), .direct("What can you tell us about your home project?", "\"I am building an addition to my house. I needed roof trusses and hired a hauler to deliver a load from a supplier.\""), .direct("How did you find {D}?", "\"A friend recommended {D} as someone who hauls materials at a fair price. I called, and we agreed to a delivery that same week.\""), .direct("What did {D} tell you about the trusses?", "\"{D} said the load was ready and that it came from a supplier. I did not ask for paperwork, because I trusted the arrangement.\""), .cross("Did you check where the trusses came from before paying?", "\"No. I did not. I trusted {D}, and I did not look at the stamps on the lumber.\""), .cross("Did you know the trusses were stolen from a subdivision lot?", "\"No. I had no idea. If I had known, I would not have accepted the delivery.\""), .cross("Are you related to {D} or close to {D}?", "\"No. I am only a customer. I hired {D} for hauling and nothing more.\""), .cross("Did you check where the trusses came from?", "\"No. I assumed they came from a supplier. In hindsight, I should have asked for the source, but I did not think about it.\""), .cross("Did you pay in cash on the day of delivery?", "\"Yes. We agreed on cash. I handed it over when the load arrived, and {D} wrote an invoice on the spot.\"")],
