        defense: [E(.statement, 1, "Own", "{DL} says the hives were {D.his}.")],
        role: "Orchard owner",
        exam: [.direct("What happened at your orchard before bloom on {DATE}?", "\"Forty beehives were taken. They're registered to me in the hive registry.\""), .direct("What was left behind?", "\"A smoker in the grass with {D}'s initials on it. A camera also shows a truck at night.\""), .direct("Why does that matter?", "\"A beekeeper's smoker goes where the beekeeper goes. {D}'s initials put {D} at my orchard.\""), .direct("Describe your orchard for the jury.", "\"I grow apples and cherries on a family orchard. Every spring I bring in hives to pollinate before bloom, and I rent most of them from local beekeepers.\""), .direct("What did you find that morning?", "\"Forty hives were gone from the edge of the orchard. The ground was flattened where they had stood, and a truck's tire marks led away.\""), .direct("What was left in the grass?", "\"A beekeeper's smoker with {D}'s initials on it. A beekeeper's smoker normally goes wherever the beekeeper goes.\""), .cross("{DL} says the hives were {D.his}, doesn't {D.he}?", "\"I can't speak to {D}'s hives. Mine are in the registry.\""), .cross("Could {DL} have dropped the smoker earlier?", "\"I suppose so, if {D} visited before. I can't say when it was dropped.\""), .cross("Can you see the truck's driver?", "\"No. It's dark. I see a truck.\""), .cross("Did {D} ever sell hives to you?", "\"Yes, earlier. {D} sold me some hives, so {D} had been to the orchard before and knew where I kept them.\""), .cross("Could the smoker have been left on an earlier visit?", "\"It could have been. I did not see it before that day, but I cannot say it was left that night rather than on an earlier visit.\"")],
        defenseRole: "Fellow beekeeper",
